function withOneMillionContext(models, familyName, defaultContextLength, liveCatalogId, supportsOneMillion = () => true) {
  return models.flatMap((model2) => {
    const defaultContextModel = {
      ...model2,
      contextLength: defaultContextLength,
      liveCatalogIds: model2.liveCatalogIds ?? [liveCatalogId],
      ...familyName.startsWith("GPT-") ? {} : { scoresAs: model2.scoresAs ?? liveCatalogId }
    };
    if (!supportsOneMillion(model2)) return [defaultContextModel];
    const oneMillionModel = {
      ...defaultContextModel,
      id: `${model2.id}-1m`,
      name: model2.name.replace(familyName, `${familyName} 1M`),
      contextLength: ONE_MILLION_CONTEXT
    };
    return [oneMillionModel, defaultContextModel];
  });
}
