function modelName(id) {
  return id.split("/").pop().split("-").map((part) => {
    const lower = part.toLowerCase();
    if (["gpt", "ai", "glm"].includes(lower)) return lower.toUpperCase();
    return part.length ? part[0].toUpperCase() + part.slice(1) : part;
  }).join(" ");
}
